          </>
        )}

        {view === 'timeline' && (
          <TimelineView
            onOpenArc={openArcInView}
            onOpenArticle={openArticleInNews}
            focusEventKey={focusTimelineEvent}
            focusArcKey={focusTimelineArc}
            investigationContext={investigationContext}
          />
        )}
        {view === 'arcs' && (
          <ArcsView
            focusArcId={focusArc}
            onOpenArticle={openArticleInNews}
            onOpenNode={openNodeInGraph}
