          />
        )}
        {view === 'phase3' && phase3Beta && <Phase3View />}
        {view === 'compare' && sourceComparisonBeta && (
          <SourceComparisonView
            onOpenArticle={openArticleInNews}
            onOpenArc={openArcInView}
            onOpenTimeline={openEventInTimeline}
