    }

    if (code === 'access_denied') {
      applyAccessFailure(code, { investigationId })
      return { ignored: false, error: code }
    }
    if (code) {
      if (asBefore) {
        applyCatalog((s) => ({ ...s, loadingBefore: false }))
        return { ignored: false, error: code }
