        ...s,
        loadingBundle: false,
        bundleError: code,
        bundle: null,
        panels: null,
        checks: null,
        checksPanels: null,
        loadingChecks: false,
        checksBusy: false,
        ...emptyReviewsState(),
      }))
      return { ignored: false, error: code }
    }

    if (!bundleMatchesRequest(result.data, investigationId, versionId)) {
      if (asBefore) {
        applyCatalog((s) => ({ ...s, loadingBefore: false }))
