  padding: 12px;
  border: 1px solid var(--border-color, #e1e7ef);
  border-radius: 8px;
  background: var(--bg-panel, #fff);
}

.piw-review-filter {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.piw-review-counts,
.piw-evidence-pick {
  margin: 8px 0 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.piw-review-counts {
  list-style: none;
}

.piw-field {
  display: grid;
  gap: 4px;
  margin: 8px 0;
  font-size: 13px;
}

.piw-field select,
.piw-field textarea,
.piw-evidence-item input[type='checkbox'] {
  font: inherit;
  max-width: 100%;
}

.piw-field select,
.piw-field textarea {
  min-height: 44px;
  padding: 8px 10px;
  border: 1px solid var(--border-color, #e1e7ef);
  border-radius: 6px;
}

.piw-evidence-item {
  padding: 8px 0;
  border-top: 1px solid var(--border-color, #e1e7ef);
}

.piw-evidence-item label {
  display: flex;
  gap: 8px;
  align-items: flex-start;
}

@media (max-width: 767px) {
  .piw {
    padding: 12px 12px 24px;
  }

  .piw-section-nav {
    position: static;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .piw-section-btn {
    flex: 0 0 auto;
    min-width: 0;
    white-space: normal;
  }

  .piw-review-filter {
    flex-wrap: wrap;
  }

  .piw-review-filter .piw-section-btn {
    flex: 1 1 160px;
    max-width: 100%;
  }
}


.piw-assessment-trail,
.piw-input-dates {
  min-width: 0;
  overflow-wrap: anywhere;
}

.piw-input-dates > div {
  margin: 8px 0;
}

.piw-input-dates dt {
  color: var(--text-secondary, #667085);
}

.piw-input-dates dd {
  margin: 2px 0 0;
  font-variant-numeric: tabular-nums;
}

.piw-retained-body {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.piw-source-history-item {
  border: 1px solid var(--border-color, #e1e7ef);
  border-radius: 8px;
  margin: 12px 0;
  background: var(--bg-primary, #fff);
  min-width: 0;
  overflow-wrap: anywhere;
}

.piw-source-history-item > summary,
.piw-source-field > summary {
  padding: 14px;
  cursor: pointer;
}

.piw-source-history-item > summary span,
.piw-source-field > summary span {
  display: inline-block;
  margin-left: 12px;
  color: var(--text-secondary, #667085);
  font-size: 12px;
}

.piw-source-history-item[open] > summary {
  background: var(--bg-secondary, #f7f9fc);
  border-bottom: 1px solid var(--border-color, #e1e7ef);
}

.piw-source-history-content { padding: 0 16px 16px; }
.piw-source-history-item h4 { margin: 20px 0 8px; }
.piw-source-history-item h5 { margin: 8px 0; }
.piw-source-pair { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
.piw-source-pair > * { min-width: 0; overflow-wrap: anywhere; }
.piw-source-capture { padding: 0 12px 12px; background: var(--bg-secondary, #f7f9fc); border-radius: 6px; }
.piw-source-fields { border-top: 1px solid var(--border-color, #e1e7ef); }
.piw-source-spans { margin: 16px 0; padding: 12px; border: 1px solid var(--border-color, #e1e7ef); border-radius: 8px; }
.piw-definition-revisions { margin: 20px 0; padding: 16px; border: 1px solid var(--border-color, #e1e7ef); border-radius: 8px; }
.piw-definition-revisions > p,
.piw-definition-revisions [data-definition-revisions] > p { margin: 8px 0; line-height: 1.5; }
.piw-definition-context { padding: 12px 0; }
.piw-definition-context > h5 { margin-bottom: 8px; }
.piw-definition-record { margin-top: 12px; border: 1px solid var(--border-color, #e1e7ef); border-radius: 6px; overflow-wrap: anywhere; }
.piw-definition-record > summary { padding: 14px; cursor: pointer; background: var(--bg-secondary, #f7f9fc); }
.piw-definition-fields { padding: 0 12px 12px; }
.piw-definition-stage { margin-top: 16px; padding-top: 8px; border-top: 2px solid var(--border-color, #e1e7ef); }
.piw-definition-revisions dd { margin: 2px 0 12px; overflow-wrap: anywhere; }
.piw-version-navigation { margin: 16px 0; padding: 16px; border: 1px solid var(--border-color, #e1e7ef); border-radius: 8px; }
.piw-version-heading, .piw-version-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.piw-version-heading h2 { margin: 0; font-size: 16px; }
.piw-version-label { padding: 5px 9px; border-radius: 5px; background: var(--bg-secondary, #edf3fe); font-size: 12px; }
.piw-version-navigation p { margin: 10px 0; line-height: 1.5; }
.piw-version-details { padding-top: 10px; border-top: 1px solid var(--border-color, #e1e7ef); }
.piw-version-details summary { cursor: pointer; padding: 4px 0; }
.piw-version-details dd { margin: 3px 0 10px; overflow-wrap: anywhere; font-size: 12px; }
.piw-version-navigation button:disabled { opacity: .55; cursor: not-allowed; }
.piw-retained-inputs { margin: 20px 0; padding: 16px; border: 1px solid var(--border-color, #e1e7ef); border-radius: 8px; }
.piw-retained-inputs p { margin: 8px 0; line-height: 1.5; }
.piw-input-search { display: flex; flex-wrap: wrap; align-items: end; gap: 12px; margin: 12px 0; }
.piw-input-search .piw-field { flex: 1 1 240px; min-width: 0; }
.piw-input-search input { box-sizing: border-box; width: 100%; min-height: 44px; padding: 10px; border: 1px solid var(--border-color, #e1e7ef); border-radius: 6px; background: var(--bg-primary, #fff); color: inherit; }
.piw-input-kind { max-width: 300px; }
.piw-input-results { list-style: none; margin: 12px 0; padding: 0; }
.piw-input-results li { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; padding: 14px 0; border-top: 1px solid var(--border-color, #e1e7ef); }
.piw-input-results li > div { flex: 1 1 260px; min-width: 0; overflow-wrap: anywhere; }
.piw-span-text { margin: 12px 0; line-height: 1.6; }
.piw-span-text mark { background: #ffebb0; color: #513808; padding: 1px 0; }
.piw-span-empty { border-inline-start: 2px solid #956419; margin-inline: 2px; }
.piw-source-field { border-bottom: 1px solid var(--border-color, #e1e7ef); }
.piw-source-field > .piw-source-pair { padding: 0 14px 14px; }
.piw-source-field summary [data-field-status='different'] { color: #8a5416; }
.piw-source-field summary [data-field-status='equal'] { color: #326843; }
.piw-source-history-item summary:focus-visible { outline: 2px solid var(--accent, #2563eb); outline-offset: 2px; }

@media (max-width: 767px) {
  .piw-source-pair { grid-template-columns: minmax(0, 1fr); }
  .piw-source-history-content { padding: 0 10px 12px; }
  .piw-source-history-item > summary span,
  .piw-source-field > summary span { display: block; margin: 6px 0 0; }
}

.piw-version-reference { display: grid; gap: .65rem; max-width: 32rem; margin: 1rem 0; }
.piw-version-reference label { font-weight: 600; }
.piw-version-reference input { width: 100%; min-width: 0; box-sizing: border-box; font: inherit; padding: .65rem; border: 1px solid var(--border, #d1d5db); border-radius: .4rem; }
.piw-version-reference button { justify-self: start; min-height: 44px; }
.piw-version-reference [role="alert"] { margin: 0; }


/* Saved assessment and generation inspection use shared workspace tokens. */
.piw-hypothesis-assessment,
.piw-generation-ledger { font-size: 13px; line-height: 1.5; }
.piw-hypothesis-assessment p,
.piw-generation-ledger p { margin: 8px 0; }
.piw-hypothesis-assessment h3,
.piw-generation-ledger h3 { font-size: 16px; margin: 0 0 12px; color: var(--text-primary); }
.piw-hypothesis-assessment h4 { margin: 16px 0 8px; font-size: 14px; }
.piw-hypothesis-assessment h5 { margin: 12px 0 6px; font-size: 13px; }
.piw-hypothesis-assessment dl > div { margin: 10px 0; }
.piw-hypothesis-assessment dt { font-weight: 600; color: var(--text-primary); }
.piw-hypothesis-assessment dd { margin: 2px 0 0; }
.piw-generation-ledger > ul { list-style: none; padding: 0; margin: 16px 0; }
.piw-generation-ledger > ul > li { padding: 12px 0; border-top: 1px solid var(--border-color); }
.piw-generation-ledger .piw-btn { max-width: 100%; white-space: normal; }
.piw-generation-ledger .piw-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }


.piw-hypothesis-composer { min-width: 0; font-size: 13px; line-height: 1.5; }
.piw-hypothesis-composer,
.piw-hypothesis-composer > form { grid-template-columns: minmax(0, 1fr); }
.piw-hypothesis-composer p { margin: 8px 0; }
.piw-hypothesis-composer h2 { font-size: 18px; margin-bottom: 12px; }
.piw-hypothesis-composer h3 { font-size: 15px; margin-bottom: 12px; }
.piw-hypothesis-composer fieldset { min-inline-size: 0; inline-size: 100%; max-inline-size: 100%; margin: 12px 0; padding: 12px; border: 1px solid var(--border-color); border-radius: 6px; }
.piw-hypothesis-composer legend { font-weight: 600; padding: 0 4px; max-width: 100%; }
.piw-hypothesis-composer .piw-field { display: block; margin: 12px 0; min-width: 0; }
.piw-hypothesis-composer .piw-field > span { min-width: 0; max-width: 100%; overflow-wrap: anywhere; }
.piw-hypothesis-composer textarea,
.piw-hypothesis-composer select,
.piw-hypothesis-composer input[type="number"] { width: 100%; min-width: 0; max-width: 100%; min-height: 44px; box-sizing: border-box; font: inherit; padding: 8px; border: 1px solid var(--border-color); border-radius: 6px; background: var(--bg-inset); color: var(--text-primary); }
.piw-hypothesis-composer .piw-field > :is(textarea, select) { display: block; margin-top: 6px; }
.piw-hypothesis-composer textarea { resize: vertical; }
/* WebKit native appearance can paint long selected text beyond its control box. */
.piw-hypothesis-composer select {
 appearance: none; overflow: hidden; text-overflow: ellipsis; padding-inline-end: 32px;
 background-image: linear-gradient(45deg, transparent 50%, var(--text-primary) 50%), linear-gradient(135deg, var(--text-primary) 50%, transparent 50%);
 background-position: right 16px center, right 11px center;
 background-size: 5px 5px; background-repeat: no-repeat;
}
.piw-hypothesis-composer button { min-height: 44px; max-width: 100%; white-space: normal; margin: 4px 4px 4px 0; padding: 8px 12px; font: inherit; border: 1px solid var(--border-color); border-radius: 6px; color: var(--cat-blue); background: var(--bg-selected); cursor: pointer; }
.piw-hypothesis-composer button:disabled { opacity: .6; cursor: not-allowed; }
.piw-hypothesis-composer :is(button,select,textarea,input):focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.piw-hypothesis-composer blockquote { margin: 12px 0; padding: 12px; border-inline-start: 2px solid var(--border-strong); white-space: pre-wrap; overflow-wrap: anywhere; }

.piw-hypothesis-review { font-size: 13px; line-height: 1.5; }
.piw-hypothesis-review p { margin: 8px 0; }
.piw-hypothesis-review h3 { font-size: 15px; margin-bottom: 12px; }

.piw-revision-comparison { min-width: 0; font-size: 13px; line-height: 1.5; overflow-wrap: anywhere; }
.piw-revision-comparison p { margin: 8px 0; }
.piw-revision-comparison h3 { font-size: 16px; margin: 0 0 12px; }
.piw-revision-comparison h4 { font-size: 14px; margin: 16px 0 8px; }
.piw-revision-comparison h5,
.piw-revision-comparison h6 { font-size: 13px; margin: 12px 0 6px; }
.piw-revision-comparison summary { min-height: 44px; padding: 12px 0; cursor: pointer; }
.piw-revision-comparison summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.piw-revision-diff-group { border-top: 1px solid var(--border-color); margin-top: 16px; }
.piw-revision-diff-values { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.piw-revision-diff-values > div { min-width: 0; padding: 12px; background: var(--bg-inset); border: 1px solid var(--border-color); border-radius: 6px; }
.piw-revision-diff-values dl { margin: 8px 0; }
.piw-revision-diff-values dt { font-weight: 600; }
.piw-revision-diff-values dd { margin: 2px 0 8px; }
.piw-revision-diff-values ul { padding-inline-start: 20px; }
@media (max-width: 600px) { .piw-revision-diff-values { grid-template-columns: minmax(0, 1fr); } }

.piw-hypothesis-history > header { font-size: 13px; line-height: 1.5; }
.piw-hypothesis-history > header h2 { font-size: 18px; margin: 0 0 12px; }
.piw-hypothesis-history > header p { margin: 8px 0; }
.piw-hypothesis-history > header button,
.piw-hypothesis-revision-select select { min-height: 44px; max-width: 100%; padding: 8px 12px; font: inherit; border: 1px solid var(--border-color); border-radius: 6px; }
.piw-hypothesis-history > header button { color: var(--cat-blue); background: var(--bg-selected); cursor: pointer; margin: 4px 4px 4px 0; white-space: normal; }
.piw-hypothesis-revision-select { font-size: 13px; line-height: 1.5; }
.piw-hypothesis-revision-select label { display: block; margin-bottom: 8px; }
.piw-hypothesis-revision-select select { display: block; width: 100%; color: var(--text-primary); background: var(--bg-inset); }
.piw-hypothesis-history > header button:focus-visible,
.piw-hypothesis-revision-select select:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.piw-comparison-notes { margin-top: 16px; border-top: 1px solid var(--border-color); }

.piw-hypothesis-observations { min-width: 0; overflow-wrap: anywhere; font-size: 13px; line-height: 1.5; }
.piw-hypothesis-observations h3 { margin: 0 0 12px; font-size: 16px; }
.piw-hypothesis-observations h4 { margin: 16px 0 8px; font-size: 14px; }
.piw-hypothesis-observations p { margin: 8px 0; }
.piw-hypothesis-observations button,
.piw-hypothesis-observations select { min-height: 44px; max-width: 100%; min-width: 0; padding: 8px 12px; font: inherit; border: 1px solid var(--border-color); border-radius: 6px; }
.piw-hypothesis-observations button { white-space: normal; margin: 4px 4px 4px 0; cursor: pointer; color: var(--cat-blue); background: var(--bg-selected); }
.piw-hypothesis-observations button:disabled { opacity: .6; cursor: not-allowed; }
.piw-hypothesis-observations label { display: block; margin: 12px 0; }
.piw-hypothesis-observations select { display: block; width: 100%; margin-top: 6px; color: var(--text-primary); background: var(--bg-inset); }
.piw-hypothesis-observations > ul { margin: 12px 0; padding-inline-start: 20px; }
.piw-hypothesis-observations summary { min-height: 44px; padding: 12px 0; cursor: pointer; }
.piw-hypothesis-observations :is(button,select,summary):focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.piw-hypothesis-observations select {
 appearance: none; overflow: hidden; text-overflow: ellipsis; padding-inline-end: 32px;
 background-image: linear-gradient(45deg, transparent 50%, var(--text-primary) 50%), linear-gradient(135deg, var(--text-primary) 50%, transparent 50%);
 background-position: right 16px center, right 11px center;
 background-size: 5px 5px; background-repeat: no-repeat;
}

/* The reassessment form also appears inside the normal App's narrow reading
   column. Bound controls to that column, not their longest option's intrinsic
   width. Keep the full label/options in the native accessible control. */
.piw-hypothesis-reassessment { font-size: 13px; line-height: 1.5; }
.piw-hypothesis-reassessment h3 { font-size: 16px; margin: 0 0 12px; }
.piw-hypothesis-reassessment p { margin: 8px 0; }
.piw-hypothesis-reassessment form { min-width: 0; }
.piw-hypothesis-reassessment label { display: block; margin: 12px 0 6px; }
.piw-hypothesis-reassessment :is(select,textarea,button) { box-sizing: border-box; min-width: 0; max-width: 100%; min-height: 44px; padding: 8px 12px; font: inherit; border: 1px solid var(--border-color); border-radius: 6px; }
.piw-hypothesis-reassessment :is(select,textarea) { display: block; width: 100%; color: var(--text-primary); background: var(--bg-inset); }
.piw-hypothesis-reassessment textarea { resize: vertical; }
.piw-hypothesis-reassessment button { white-space: normal; color: var(--cat-blue); background: var(--bg-selected); cursor: pointer; }
.piw-hypothesis-reassessment button:disabled { opacity: .6; cursor: not-allowed; }
.piw-hypothesis-reassessment :is(select,textarea,button):focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.piw-hypothesis-reassessment select {
 appearance: none; overflow: hidden; text-overflow: ellipsis; padding-inline-end: 32px;
 background-image: linear-gradient(45deg, transparent 50%, var(--text-primary) 50%), linear-gradient(135deg, var(--text-primary) 50%, transparent 50%);
 background-position: right 16px center, right 11px center;
 background-size: 5px 5px; background-repeat: no-repeat;
}

/* Investigation workspace shell — cool white canvas.
   Layout tokens restore the reviewed target frame:
   190px rail (72px collapsed), compact 48px desktop toolbar,
   286px inspector beside the question and evidence on wide screens. */

.workspace-app,
.ws-shell {
  --sidebar: 190px;
  --inspector: 286px;
  --topbar: 48px;
  --bg-page: #f6f8fb;
  --bg-panel: #fff;
  --bg-elevated: #f0f4fa;
  --bg-inset: #f8fafc;
  --bg-selected: #eaf0ff;
  --border-color: #e1e7ef;
  --border-strong: #becbdd;
  --text-primary: #202c41;
  --text-body: #39465b;
  --text-secondary: #56657b;
  --text-muted: #647187;
  --cat-blue: #315dbe;
  --accent: #315dbe;
  --accent-rgb: 49, 93, 190;
  --card-radius: 8px;
  --view-pad-top: 16px;
  --graph-grid: rgba(52, 76, 114, 0.045);
  display: grid;
  grid-template-columns: var(--sidebar) minmax(0, 1fr);
  grid-template-rows: var(--topbar) auto minmax(0, 1fr) auto;
  height: 100%;
  max-height: 100dvh;
  font-size: 13px;
  overflow: hidden;
  background: var(--bg-page);
  color: var(--text-primary);
}

.workspace-app.nav-collapsed,
.ws-shell.ws-nav-collapsed {
  --sidebar: 72px;
}

/* Owner's Graph / Timeline / Arcs / Comparison reference shares one tall
   inspector. Native graph/globe inspectors keep ownership of their layout. */
@media (min-width: 1280px) {
  .ws-shell:not(:has(.ws-body.has-native-inspector)) {
    grid-template-columns: var(--sidebar) minmax(0, 1fr) var(--inspector);
  }

  .ws-shell:not(:has(.ws-body.has-native-inspector)) > .ws-topbar {
    grid-column: 2 / -1;
  }

  .ws-shell > .ws-body:not(.has-native-inspector) {
    display: contents;
  }

  .ws-shell > .ws-body:not(.has-native-inspector) > .ws-content {
    grid-column: 2;
    grid-row: 3;
  }

  .ws-shell > .ws-body:not(.has-native-inspector) > .ws-inspector {
    grid-column: 3;
    grid-row: 2 / 4;
    min-height: 0;
  }
}

.ws-private-context {
  margin-top: 8px;
}

.ws-page-scroll { display: none; }

@media (max-width: 767px) {
  .ws-page-scroll {
    position: fixed;
    z-index: 25;
    right: env(safe-area-inset-right, 0px);
    top: 45%;
    display: flex;
    align-items: center;
    flex-direction: column;
    width: 28px;
    padding: 6px 0;
    border: 1px solid var(--border-strong);
    border-radius: 14px;
    background: var(--bg-panel);
    color: var(--cat-blue);
    box-shadow: 0 1px 5px #202c4126;
  }
  .ws-page-scroll input {
    writing-mode: vertical-lr;
    direction: ltr;
    width: 28px;
    height: 28dvh;
    min-height: 100px;
    margin: 4px 0;
    accent-color: var(--cat-blue);
    cursor: pointer;
  }
  .ws-shell:is([data-workspace-view='world'], [data-workspace-view='investigations']) {
    padding-right: 30px;
    box-sizing: border-box;
    scrollbar-width: none;
  }
  .ws-shell:is([data-workspace-view='world'], [data-workspace-view='investigations'])::-webkit-scrollbar { width: 0; }
}

.ws-private-context summary {
  min-height: 44px;
  align-content: center;
  color: var(--cat-blue);
  cursor: pointer;
}

.app.ws-app {
  display: block;
  height: 100%;
  overflow: hidden;
}

.ws-app .app-header,
.ws-app .bottom-nav {
  display: none;
}

.ws-app .ic-bar {
  border-bottom: 0;
}

.ws-app .app-main {
  flex: 1;
  min-height: 0;
  min-width: 0;
  height: 100%;
  overflow: auto;
}

.ws-nav {
  grid-column: 1;
  grid-row: 1 / -1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  border-right: 1px solid var(--border-color);
  background: var(--bg-panel);
}

.ws-nav-brand {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 12px 10px;
  min-height: var(--topbar);
}

.ws-mobius {
  display: block;
  width: 33px;
  height: 33px;
  flex: 0 0 33px;
  object-fit: contain;
}

.ws-brand-wordmark {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.15;
}

.ws-brand-mip {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--text-primary);
}

.ws-brand-name {
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-secondary);
}

.ws-logo {
  display: none;
}

.ws-nav-links {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px;
  flex: 1;
  overflow: auto;
}

.ws-nav-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  border: 0;
  border-radius: 6px;
  background: transparent;
