}

@media (min-width: 768px) {
  .ws-menu-btn {
    display: none;
  }

  .ws-nav {
    display: flex;
  }
}

@media (max-width: 767px) {
  .workspace-app,
  .ws-shell {
    --sidebar: 0px;
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: 56px auto minmax(0, 1fr) auto;
    overflow-x: hidden;
  }

  .ws-nav {
    display: none;
  }

  .ws-menu-btn {
    display: inline-flex;
  }

  .ws-topbar,
  .ws-workspace-head,
  .workspace-body,
  .ws-body,
  .ws-details {
    grid-column: 1;
  }

  .ws-topbar {
    height: 56px;
    min-height: 56px;
    gap: 4px;
    padding-inline: 8px;
  }

  .ws-top-meta {
    flex-shrink: 0;
    gap: 0;
  }

  .ws-topbar :is(.ws-account-btn, .ws-icon-btn, .ws-menu-btn) {
    flex: 0 0 44px;
    width: 44px;
    min-height: 44px;
    padding: 0;
    justify-content: center;
  }

  .ws-search {
    gap: 4px;
    padding-inline: 4px;
  }

  .ws-search > svg {
    display: none;
  }

  .ws-explore-btn {
    padding-inline: 8px;
  }

  .ws-brand-name,
  .ws-corpus,
  .ws-account-label {
    display: none;
  }

  .workspace-evidence-strip,
  .ws-dimensions {
    display: flex;
    overflow-x: auto;
    border-bottom: 1px solid var(--border-color);
  }

  .ws-dimension {
    flex: 0 0 148px;
    min-width: 148px;
  }

  .ws-canonical-head {
    flex-direction: column;
  }

  .ws-title {
    font-size: 20px;
  }

  .workspace-body,
  .ws-body {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr) auto;
  }

  .ws-inspector {
    position: sticky;
    bottom: 0;
    width: 100%;
    max-width: 100%;
    max-height: 46vh;
    border-left: 0;
    border-top: 1px solid var(--border-color);
    overflow-x: hidden;
  }

  .ws-inspector.collapsed {
    width: 100%;
    max-height: none;
  }

  /* Reading an investigation needs document flow, not the camera canvas's
     remaining-height viewport. Keep one scroll owner for header and evidence. */
  .ws-shell:is([data-workspace-view='investigations'], [data-workspace-view='world']) {
    display: block;
    overflow-y: auto;
    overflow-x: hidden;
  }

  .ws-shell:is([data-workspace-view='investigations'], [data-workspace-view='world']) .ws-body {
    display: block;
    overflow: visible;
  }

  .ws-shell:is([data-workspace-view='investigations'], [data-workspace-view='world']) .ws-content,
  .ws-shell:is([data-workspace-view='investigations'], [data-workspace-view='world']) .app-main {
    height: auto;
    overflow: visible;
    min-width: 0;
  }

  .ws-shell:is([data-workspace-view='investigations'], [data-workspace-view='world']) .ws-inspector {
    position: static;
    max-height: none;
  }

  .ws-shell:is([data-workspace-view='investigations'], [data-workspace-view='world']) .ws-dimensions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    overflow: visible;
  }

  .ws-shell:is([data-workspace-view='investigations'], [data-workspace-view='world']) .ws-dimension {
    min-width: 0;
    border-bottom: 1px solid var(--border-color);
  }

  .ws-shell:is([data-workspace-view='investigations'], [data-workspace-view='world']) .ws-canonical {
    padding: 12px 16px 0;
  }

  .ws-shell:is([data-workspace-view='investigations'], [data-workspace-view='world']) .ws-title {
    font-size: 18px;
    overflow-wrap: anywhere;
  }
}


/* Shared frame refinement from the owner's September reference set.
   Collapse changes the layout track, not only the visible panel width. */
@media (min-width: 1024px) {
  .ws-shell[data-inspector-state='collapsed'] {
    --inspector: 48px;
  }

  .ws-shell:not(:has(.ws-body.has-native-inspector)) {
    grid-template-columns: var(--sidebar) minmax(0, 1fr) var(--inspector);
  }

  .ws-shell:not(:has(.ws-body.has-native-inspector)) > .ws-topbar {
    grid-column: 2 / -1;
  }

  .ws-shell > .ws-body:not(.has-native-inspector) {
    display: contents;
  }

  .ws-shell > .ws-body:not(.has-native-inspector) > .ws-content {
    grid-column: 2;
    grid-row: 3;
  }

  .ws-shell > .ws-body:not(.has-native-inspector) > .ws-inspector {
    grid-column: 3;
    grid-row: 2 / 4;
    min-height: 0;
  }

  .ws-inspector.collapsed .ws-inspector-toggle {
    writing-mode: vertical-rl;
    justify-content: flex-start;
    min-height: 220px;
    padding: 16px 12px;
  }
}

.ws-canonical-copy {
  flex: 1;
  min-width: 0;
}

.ws-canonical-head > .ws-change-btn {
  flex-shrink: 0;
}

.ws-canonical .ws-title {
  overflow-wrap: anywhere;
}

.ws-topbar { gap: 12px; }
.ws-canonical { padding: 12px 16px 0; }
.ws-dimensions { margin-top: 12px; }
.ws-dimension { padding: 8px 10px; }
.ws-tabs { gap: 2px; padding: 6px 12px; }
.ws-tab { font-size: 12px; padding: 7px 9px; }
.ws-inspector-toggle { min-height: 44px; }
.ws-inspector-body { padding: 0 14px 18px; }

.ws-nav-btn:focus-visible,
.ws-tab:focus-visible,
.ws-inspector-toggle:focus-visible,
.ws-collapse-btn:focus-visible {
  outline: 2px solid var(--cat-blue);
  outline-offset: -2px;
}

/* Tablet reading space: put the shared inspector below the evidence instead
   of squeezing both into narrow side-by-side columns. Native canvases retain
   their own inspector behavior. */
@media (min-width: 768px) and (max-width: 1023px) {
  .ws-shell { --sidebar: 160px; }
  .ws-shell.ws-nav-collapsed { --sidebar: 72px; }
  .ws-body:not(.has-native-inspector) {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(180px, 1fr) auto;
  }
  .ws-body:not(.has-native-inspector) > .ws-inspector {
    width: 100%;
    max-height: 32dvh;
    border-left: 0;
    border-top: 1px solid var(--border-color);
  }
  .ws-inspector.collapsed { max-height: 44px; }
  .ws-canonical-head { flex-wrap: wrap; gap: 8px; }
  .ws-canonical-head > .ws-change-btn { margin-top: 0; }
}

@media (max-width: 767px) {
  .ws-topbar { gap: 4px; }
  .ws-tabs { padding-inline: 8px; }
  .ws-tab { min-height: 44px; font-size: 13px; padding-inline: 10px; }
  .ws-drawer-nav .ws-nav-btn,
  .ws-drawer-head .ws-icon-btn { min-height: 44px; }
}


@media (max-width: 1100px) {
  /* Preserve search space before optional corpus metadata. */
  .ws-corpus { display: none; }
}

@media (max-width: 767px) {
  /* Reading views use one page scroll. A tall header plus an open inspector
     must not reduce evidence to a thin, independently scrolling strip. */
  .ws-shell:is([data-workspace-view='news'], [data-workspace-view='timeline'], [data-workspace-view='arcs'], [data-workspace-view='compare']) {
    display: block;
    overflow-y: auto;
  }
  .ws-shell:is([data-workspace-view='news'], [data-workspace-view='timeline'], [data-workspace-view='arcs'], [data-workspace-view='compare']) .ws-body {
    display: block;
    overflow: visible;
  }
  .ws-shell:is([data-workspace-view='news'], [data-workspace-view='timeline'], [data-workspace-view='arcs'], [data-workspace-view='compare']) :is(.ws-content, .app-main) {
    height: auto;
    overflow: visible;
  }
  .ws-shell:is([data-workspace-view='news'], [data-workspace-view='timeline'], [data-workspace-view='arcs'], [data-workspace-view='compare']) .ws-inspector {
    position: static;
    width: 100%;
    max-height: none;
  }
}

@media (max-width: 720px) {
  .ws-shell .timeline-search {
    flex: 0 0 auto;
    min-height: 44px;
    min-width: 0;
  }
}

@import './styles/tokens.css';
* {
  box-sizing: border-box;
  margin: 0;
}

html,
body,
#root {
  height: 100%;
  height: 100dvh;
  max-height: 100dvh;
}

body {
  font-family: var(--font-sans);
  background: var(--bg-page);
  color: var(--text-primary);
}

.app {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.app-header {
  display: flex;
  align-items: baseline;
  gap: 12px;
  padding: 12px 20px;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-panel);
}

.app-header h1 {
  font-size: 20px;
  letter-spacing: 2px;
}

.subtitle {
  color: var(--text-secondary);
  font-size: 13px;
}

.app-nav {
  display: flex;
  gap: 4px;
  margin-left: 24px;
}

.nav-tab {
  background: none;
  border: 1px solid transparent;
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 13px;
  padding: 5px 12px;
  cursor: pointer;
}

.nav-tab:hover {
  color: var(--text-primary);
}

.nav-tab.active {
  color: var(--text-primary);
  border-color: var(--accent);
  background: rgba(var(--accent-rgb), 0.12);
}

.data-source {
  margin-left: auto;
  color: var(--text-muted);
  font-size: 12px;
}

.app-main {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

/* R4.75 Step 1 — shared Investigation Context (DISPLAY only). */
.ic-bar {
  padding: 8px 20px 10px;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-panel);
}

.ic-bar-title {
  margin: 0 0 4px;
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.ic-bar-empty {
  margin: 0;
  font-size: 12px;
  color: var(--text-secondary);
}

.ic-bar-fields {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  margin: 0;
}

.ic-bar-fields > div {
  min-width: 12rem;
}

.ic-bar-fields dt {
  font-size: 10px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.ic-bar-fields dd {
  margin: 0;
  font-size: 12px;
  color: var(--text-primary);
  word-break: break-all;
}

.ic-bar-fallbacks {
  margin: 8px 0 0;
  padding-left: 1.1rem;
  font-size: 12px;
  color: var(--text-secondary);
}

.ic-bar-joins {
  margin: 8px 0 0;
  padding-left: 1.1rem;
  font-size: 12px;
  color: var(--text-secondary);
}

.ic-bar-joins [data-join-kind] {
  border-left: 2px solid var(--border-color);
  padding-left: 8px;
  margin: 4px 0;
  list-style: none;
}

.ic-bar-freshness {
  margin: 8px 0 0;
  font-size: 12px;
  color: var(--text-secondary);
}

.ic-bar-recent {
  margin-top: 8px;
}

.ic-bar-recent-title {
  margin: 0 0 2px;
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.ic-bar-recent-note {
  margin: 0 0 6px;
  font-size: 11px;
  color: var(--text-secondary);
}

.ic-bar-recent-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.ic-bar-recent-item {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 1px;
  max-width: 22rem;
  padding: 4px 8px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background: transparent;
  color: var(--text-primary);
  cursor: pointer;
  text-align: left;
}

.ic-bar-recent-item:hover {
  border-color: var(--accent);
}

.ic-bar-recent-type,
.ic-bar-recent-view {
  font-size: 10px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.ic-bar-recent-id {
  font-size: 12px;
  word-break: break-all;
}

/* R4.75 Step 4 — two filter families. Discovery (News / Explore) and
   investigation (Graph / World View / Timeline) stay visually distinct. */
.filter-family-label {
  margin: 0;
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.filter-family-note {
  margin: 0;
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.4;
}

.wv-ic {
  margin: 0 0 12px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border-color);
}

.wv-ic h4 {
  margin: 0 0 8px;
  font-size: var(--fs-meta);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-secondary);
}

.notice {
  padding: 20px;
  color: var(--text-secondary);
}

.notice.error {
  color: var(--cat-red);
}

/* ---------- Graph tab: canvas + slide-in article panel ---------- */

.graph-layout {
  --graph-canvas-min: 360px;
  position: relative;
  display: flex;
  flex: 1;
  min-height: 0;
  min-width: 0;
}

/* Tablet drawer overlay: isolate so the backdrop and drawers share one
   stacking context. Do not give .graph-area a z-index here — that would
   trap the nested relationship drawer under the scrim. */
.graph-layout.inspector-overlay {
  isolation: isolate;
  --graph-overlay-scrim: 20;
  --graph-overlay-drawer: 30;
}

.graph-layout.inspector-overlay .ap-scrim {
  z-index: var(--graph-overlay-scrim);
  background: transparent;
}

/* A configured live corpus may have articles before graph publication. Keep
   that state explicit rather than substituting unrelated demonstration data. */
.graph-empty-state {
  margin: 24px;
  max-width: 680px;
  padding: 24px;
  border: 1px solid var(--border-color);
  border-radius: var(--card-radius);
  background: var(--bg-panel);
}

.graph-empty-state h2 {
  margin: 0 0 10px;
  font-size: 20px;
}

.graph-empty-state p {
  margin: 0;
  color: var(--text-secondary);
  line-height: 1.55;
}

.graph-empty-state p + p {
  margin-top: 10px;
}

.graph-area {
  position: relative;
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

/* Track B Step 2 item 1: graph chrome in normal flow — toolbar on top,
   rail beside the canvas. Nothing floats over the canvas. */
.graph-toolbar {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-panel);
}

.graph-toolbar .graph-search {
  flex: 0 1 320px;
}

.graph-toolbar-btn {
  min-height: 32px;
  padding: 4px 12px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
  white-space: nowrap;
}

.graph-toolbar-btn:hover {
  color: var(--text-primary);
  border-color: var(--border-strong);
}

.graph-toolbar-btn[aria-expanded='true'] {
  border-color: var(--accent);
  color: var(--text-primary);
}

/* Item 3: "Focused view" return control (desktop full-graph opt-out).
   Truncates long hub labels instead of stretching the toolbar. */
.graph-toolbar-focus-btn {
  max-width: 280px;
  overflow: hidden;
  text-overflow: ellipsis;
}

.graph-body {
  display: flex;
  flex: 1 1 auto;
  min-height: var(--graph-canvas-min);
  min-width: 0;
}

.graph-rail {
  flex: 0 0 240px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px;
  overflow-y: auto;
  border-right: 1px solid var(--border-color);
  background: var(--bg-panel);
}

.graph-stage {
  position: relative;
  flex: 1;
  min-width: 0;
  min-height: var(--graph-canvas-min);
}

/* C3: grid canvas sits under the (transparent) cytoscape layers and is
   redrawn from pan/zoom so it lives in canvas coordinate space. */
.graph-canvas-wrap {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: var(--graph-canvas-min);
  overflow: hidden;
}

.graph-grid {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
}

.graph-canvas {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: transparent;
}

.legend {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px 14px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: var(--card-radius);
  font-size: 12px;
}

/* Collapse toggle: the parent legend ignores pointer events, so the
   interactive bits opt back in explicitly. */
.legend-toggle,
.legend-collapsed {
  pointer-events: auto;
  cursor: pointer;
}

.legend-header {
  display: flex;
  justify-content: flex-end;
}

.legend-toggle {
  background: none;
  border: none;
  color: var(--text-secondary);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 0;
}

.legend-toggle:hover {
  color: var(--text-primary);
}

/* Collapsed state: a single-line chip at the top of the rail. */
.legend-collapsed {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: var(--card-radius);
  color: var(--text-secondary);
  font-size: 12px;
  font-family: inherit;
}

.legend-collapsed:hover {
  color: var(--text-primary);
  border-color: var(--border-strong);
}

.legend-note {
  color: var(--text-muted);
  font-size: 11px;
  margin: 0;
}

.legend h3 {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.legend-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 1px 0;
}

.legend-octagon {
  width: 14px;
  height: 14px;
  border: 3px solid;
  background: var(--bg-panel);
  clip-path: polygon(
    30% 0%, 70% 0%, 100% 30%, 100% 70%, 70% 100%, 30% 100%, 0% 70%, 0% 30%
  );
}

.legend-line {
  width: 22px;
  height: 3px;
  border-radius: 2px;
}

/* Step 7 (§3.3): dashed sample for MIP hypothesis edges. */
.legend-line--dashed {
  background: repeating-linear-gradient(
    90deg,
    var(--cat-grey) 0 4px,
    transparent 4px 7px
  );
}

/* Step 6 (§4): shape vocabulary — legend swatches mirror the cytoscape
   silhouettes keyed off node type (theme.js NODE_TYPES[].shape). */
.legend-shape {
  width: 14px;
  height: 14px;
  border: 3px solid;
  background: var(--bg-panel);
  flex-shrink: 0;
}

.legend-shape--octagon {
  clip-path: polygon(
    30% 0%, 70% 0%, 100% 30%, 100% 70%, 70% 100%, 30% 100%, 0% 70%, 0% 30%
  );
}

.legend-shape--round {
  border-radius: 4px;
}

.legend-shape--diamond {
  clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);
}

.legend-shape--barrel {
  border-radius: 45% / 25%;
}

/* Step 7 (§6): reliability scale, 1 = highest. */
.legend-reliability {
  gap: 6px;
}

.legend-rel-pip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border: 1px solid var(--border-strong);
  border-radius: 4px;
  color: var(--text-secondary);
  font-size: 11px;
}

.legend-rel-note {
  color: var(--text-muted);
  font-size: 11px;
}

/* ---------- Step 7/8: graph filter controls (stacked in the left rail) ---------- */

.graph-controls {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: var(--card-radius);
  font-size: 12px;
  color: var(--text-secondary);
}

.graph-control-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.graph-control-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
}

.graph-stepper-btn {
  min-width: 28px;
  min-height: 28px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-primary);
  font-size: 14px;
  cursor: pointer;
  line-height: 1;
}

.graph-stepper-btn:disabled {
  opacity: 0.4;
  cursor: default;
}

.graph-stepper-btn:not(:disabled):hover {
  border-color: var(--accent);
}

.graph-stepper-value {
  min-width: 14px;
  text-align: center;
  color: var(--text-primary);
}

.graph-control-toggle {
  cursor: pointer;
}

.graph-control-toggle input {
  accent-color: var(--accent);
}

.graph-topics-btn {
  min-height: 32px;
  background: rgba(var(--accent-rgb), 0.12);
  border: 1px solid var(--accent);
  border-radius: 6px;
  color: var(--accent-soft);
  font-size: 12px;
  cursor: pointer;
}

.graph-topics-btn:hover {
  color: var(--text-primary);
}

/* ---------- Step 9: focus breadcrumb trail ---------- */

.focus-trail {
  display: flex;
  align-items: center;
  align-self: center;
  gap: 8px;
  max-width: min(90%, 720px);
  margin: 8px 12px 0;
  padding: 6px 10px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: var(--card-radius);
  font-size: 12px;
}

.focus-back {
  flex-shrink: 0;
  min-width: 28px;
  min-height: 28px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-primary);
  cursor: pointer;
  line-height: 1;
}

.focus-back:hover {
  border-color: var(--accent);
}

.focus-crumbs {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
  padding: 0;
  overflow-x: auto;
  white-space: nowrap;
  min-width: 0;
}

.focus-crumb {
  display: flex;
  align-items: center;
  gap: 4px;
}

.focus-sep {
  color: var(--text-muted);
}

.focus-crumb-btn {
  background: none;
  border: none;
  border-radius: 4px;
  color: var(--accent-soft);
  font-size: 12px;
  cursor: pointer;
  padding: 4px 6px;
  max-width: 180px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.focus-crumb-btn:hover {
  background: var(--bg-elevated);
}

.focus-crumb-btn.current {
  color: var(--text-primary);
  font-weight: 600;
  cursor: default;
}

/* Item 3: the desktop default-focus crumb is documentation, not a
   breadcrumb button — same rhythm, secondary ink, no hover. */
.focus-crumb-static {
  color: var(--text-secondary);
  font-size: 12px;
  padding: 4px 6px;
  max-width: 280px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.focus-show-all {
  flex-shrink: 0;
  background: none;
  border: 1px solid var(--accent);
  border-radius: 6px;
  color: var(--accent-soft);
  font-size: 12px;
  padding: 4px 10px;
  cursor: pointer;
}

.focus-show-all:hover {
  color: var(--text-primary);
}

/* ---------- Step 7: edge evidence popover ---------- */

.edge-evidence-backdrop {
  position: fixed;
  inset: 0;
  z-index: 55;
}

.edge-evidence {
  position: fixed;
  /* Default (e.g. opened from the article panel): centered card. Tapped
     edges override with inline left/top + transform:none. */
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 56;
  width: 290px;
  max-width: calc(100vw - 16px);
  max-height: 60vh;
  overflow-y: auto;
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: var(--card-radius);
  padding: 12px 14px;
  font-size: 12px;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.45);
}

.edge-evidence-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.edge-evidence-kind {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--cat-green);
}

.edge-evidence-kind.inferred {
  color: var(--cat-amber);
}

.edge-evidence-pair {
  color: var(--text-body);
  margin-bottom: 8px;
  line-height: 1.4;
}

.edge-evidence-row {
  display: flex;
  gap: 10px;
  padding: 3px 0;
}

.edge-evidence-key {
  flex-shrink: 0;
  width: 108px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-size: 10px;
  padding-top: 1px;
}

.edge-evidence-val {
  color: var(--text-body);
  line-height: 1.45;
  min-width: 0;
}

/* ---------- Step 8: topic browser ---------- */

/* Track B Step 2 item 1: docked panel in the graph rail (no longer a
   full-screen sheet over the canvas). */
.topic-browser {
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: var(--card-radius);
  padding: 10px 12px;
  font-size: 12px;
  max-height: 50vh;
  overflow-y: auto;
}

.topic-browser .topic-back {
  background: none;
  border: none;
  color: var(--accent-soft);
  font-size: 13px;
  cursor: pointer;
  padding: 4px 0;
  margin-bottom: 8px;
}

.topic-list {
  list-style: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.topic-item {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 8px 10px;
}

.topic-name {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: baseline;
  gap: 8px;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 14px;
  text-align: left;
  cursor: pointer;
  padding: 0;
}

.topic-name.topic-leaf {
  cursor: default;
}

.topic-count {
  color: var(--text-muted);
  font-size: 11px;
}

.topic-focus-btn {
  flex-shrink: 0;
  background: rgba(var(--accent-rgb), 0.12);
  border: 1px solid var(--accent);
  border-radius: 6px;
  color: var(--accent-soft);
  font-size: 12px;
  min-height: 32px;
  padding: 4px 12px;
  cursor: pointer;
}

.topic-focus-btn:disabled {
  opacity: 0.4;
  border-color: var(--border-color);
  color: var(--text-muted);
  cursor: default;
}

/* Step 7: evidence affordance on connected-node rows (article panel). */
.ap-connection-row {
  display: flex;
  align-items: stretch;
  min-width: 0;
  gap: 4px;
}

.ap-connection-row .ap-connection {
  flex: 1;
  min-width: 0;
}

/* Connection selection belongs to a single documented row. Use a solid,
   opaque fill inside that row's own border; never draw one outline around the
   surrounding list, because several relationships can coexist in the table. */
.ap-connection-row.selected .ap-connection {
  background: color-mix(in srgb, var(--accent) 16%, var(--bg-panel));
  border-color: color-mix(in srgb, var(--accent) 68%, var(--border-color));
  box-shadow: inset 3px 0 0 var(--accent);
}
.ap-connection-row.selected .ap-conn-evidence {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 16%, var(--bg-panel));
  border-color: color-mix(in srgb, var(--accent) 68%, var(--border-color));
}


.ap-conn-evidence {
  flex-shrink: 0;
  background: none;
  border: 1px solid transparent;
  border-radius: 6px;
  color: var(--text-muted);
  font-size: 13px;
  cursor: pointer;
  padding: 0 8px;
}

.ap-conn-evidence:hover {
  color: var(--accent-soft);
  border-color: var(--border-color);
  background: var(--bg-elevated);
}

/* ---------- Location corroboration badge + credibility boost (formerly "Sky verification" — deprecated name per 02A Amendment B) ---------- */

/* Muted, honest block in the classifier-transparency visual language —
   bordered case-file card, small-caps label, mono numbers. */
.sky-badge {
  display: flex;
  flex-direction: column;
  gap: 3px;
  border: var(--border-width) solid var(--border-color);
  border-left: 3px solid var(--accent);
  border-radius: var(--card-radius);
  background: var(--bg-panel);
  padding: 10px 12px;
  margin-bottom: 14px;
}

.sky-badge-label {
  font-size: var(--fs-label);
  font-weight: var(--fw-label);
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
}

.sky-badge-line {
  font-size: var(--fs-body);
  color: var(--text-body);
  line-height: 1.45;
}

.sky-badge-caption {
  font-size: var(--fs-meta);
  color: var(--text-muted);
}

/* Task 6: the boost marker sits next to the adjusted score so the shift
   is legible, not silent. */
.sky-boost-marker {
  margin-left: 8px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--accent-soft);
  border: 1px solid var(--accent);
  border-radius: 999px;
  padding: 1px 8px;
  white-space: nowrap;
}

.sky-companion-hint {
  font-size: var(--fs-meta);
  color: var(--text-muted);
  margin-bottom: 12px;
}

.news-badge.sky {
  border-color: var(--accent);
  color: var(--accent-soft);
}

@media (max-width: 767px) {
  .sky-badge-line,
  .sky-badge-caption,
  .sky-companion-hint {
    font-size: 15px;
  }
}

/* ---------- Step 10 (§7.4): policy consequence view ---------- */

.policy-panel {
  width: 420px;
}

.pp-status,
.pp-instrument {
  border-color: var(--border-strong);
  color: var(--text-secondary);
}

.pp-center {
  border: var(--border-width) solid var(--border-color);
  border-radius: var(--card-radius);
  padding: var(--card-pad-y) var(--card-pad-x);
  background: var(--bg-inset);
}

.pp-facts {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 14px;
  margin: 0;
}

.pp-facts dt {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
}

.pp-facts dd {
  margin: 0;
  font-size: 13px;
  color: var(--text-body);
}

.pp-links {
  display: flex;
  gap: 14px;
  margin: 10px 0 0;
}

.pp-links a {
  color: var(--accent-soft);
  font-size: 13px;
}

.pp-track-filter {
  display: flex;
  gap: 6px;
  margin-bottom: 14px;
}

.pp-filter-chip {
  flex: 1;
  min-height: 32px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
}

.pp-filter-chip.active {
  color: var(--text-primary);
  border-color: var(--accent);
  background: rgba(var(--accent-rgb), 0.12);
}

.pp-track {
  margin-bottom: 18px;
}

.pp-track-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
  margin-bottom: 8px;
}

/* §3.4: the two evidence tracks sit side by side when they fit. */
.pp-evidence-tracks {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}

.pp-evidence-col {
  flex: 1 1 0;
  min-width: 0;
}

.pp-evidence-label {
  display: block;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 6px;
}

.pp-evidence-label.supports {
  color: var(--cat-green);
}

.pp-evidence-label.disputes {
  color: var(--cat-red);
}

.pp-items {
  list-style: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.pp-item {
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 8px 10px;
}

.pp-item.inferred {
  border-style: dashed;
}

.pp-item-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
}

.pp-item-rel {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-secondary);
}

/* Consequence TYPE chip — neutral, never valence-colored. */
.pp-ctype {
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  padding: 1px 8px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-secondary);
}

.pp-hypothesis-tag {
  border: 1px dashed var(--cat-amber);
  border-radius: 999px;
  padding: 1px 8px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--cat-amber);
}

.pp-item-target {
  display: block;
  width: 100%;
  background: none;
  border: none;
  padding: 0;
  color: var(--text-primary);
  font-size: 13px;
  line-height: 1.35;
  text-align: left;
  cursor: pointer;
}

.pp-item-target:hover {
  color: var(--accent-soft);
}

.pp-item-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 10px;
  margin-top: 4px;
  font-size: 11px;
  color: var(--text-muted);
}

.pp-alternatives {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 6px;
}

/* §3.4: unexamined alternatives are always visible, never hidden. */
.pp-alt-chip {
  border: 1px solid var(--cat-amber);
  border-radius: 6px;
  padding: 3px 8px;
  font-size: 11px;
  color: var(--cat-amber);
}

.pp-reasoning {
  margin-top: 6px;
}

.pp-reasoning-toggle {
  background: none;
  border: none;
  padding: 0;
  color: var(--cat-amber);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  cursor: pointer;
}

.pp-reasoning-body {
  margin: 6px 0 0;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 3px 10px;
}

.pp-reasoning-body dt {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-muted);
}

.pp-reasoning-body dd {
  margin: 0;
  font-size: 12px;
  color: var(--text-body);
}

.pp-sequence-only {
  grid-column: 1 / -1;
  color: var(--cat-amber);
}

@media (max-width: 767px) {
  .policy-panel {
    width: 100%;
  }

  .policy-panel.sheet-mode {
    max-height: 75vh;
  }

  .pp-evidence-tracks {
    flex-direction: column;
  }

  .pp-evidence-col {
    width: 100%;
  }

  .pp-filter-chip {
    min-height: 44px;
    font-size: 15px;
  }

  .pp-item-target,
  .pp-facts dd,
  .pp-reasoning-body dd {
    font-size: 15px;
  }
}

/* ---------- Article panel (§4.4) ---------- */

.article-panel {
  width: 360px;
  flex-shrink: 0;
  overflow-y: auto;
  padding: 18px 20px;
  background: var(--bg-panel);
  border-left: 1px solid var(--border-color);
  animation: ap-slide-in 0.22s ease-out;
}

.article-panel.pinned {
  border-left-color: var(--accent);
}

@keyframes ap-slide-in {
  from {
    transform: translateX(40px);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

.ap-header {
  margin-bottom: 14px;
}

.ap-title-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 8px;
}

.ap-title-row h2 {
  font-size: 17px;
  line-height: 1.3;
}

.ap-actions {
  display: flex;
  gap: 4px;
  flex-shrink: 0;
}

.ap-icon-btn {
  background: none;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-secondary);
  width: 26px;
  height: 26px;
  font-size: 14px;
  cursor: pointer;
  line-height: 1;
}

.ap-icon-btn:hover {
  color: var(--text-primary);
  border-color: var(--accent);
}

.ap-icon-btn.active {
  color: var(--accent);
  border-color: var(--accent);
}

.ap-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}

.ap-tag {
  display: inline-block;
  padding: 2px 10px;
  border: 1px solid;
  border-radius: 999px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.ap-tag-type {
  opacity: 0.75;
}

.ap-section {
  margin-bottom: 18px;
}

.ap-label {
  display: block;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
  margin-bottom: 6px;
}
.ap-evidence-axes {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  margin: 0;
}
.ap-evidence-axis {
  min-width: 0;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 7px 8px;
  background: var(--surface-subtle, rgba(0, 0, 0, 0.025));
}
.ap-evidence-axis dt {
  margin-bottom: 2px;
  font-size: 10px;
  line-height: 1.2;
  color: var(--text-muted);
}
.ap-evidence-axis dd {
  margin: 0;
  font-size: 11px;
  line-height: 1.3;
  color: var(--text-body);
}
.ap-evidence-axis.tone-unavailable dd {
  color: var(--text-muted);
}

.ap-confidence-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 4px;
}

.ap-confidence-row .ap-label {
  margin-bottom: 0;
}

.ap-confidence-value {
  font-size: 15px;
  font-weight: 600;
}

.ap-confidence-bar {
  height: 6px;
  border-radius: 3px;
  background: var(--border-color);
  overflow: hidden;
}

.ap-confidence-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.3s ease-out;
}

.ap-summary {
  font-size: 13px;
  line-height: 1.55;
  color: var(--text-body);
}

.ap-muted {
  font-size: 12px;
  color: var(--text-muted);
}

.ap-sources-error {
  font-size: 12px;
  color: var(--cat-red);
}

.ap-sources {
  list-style: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ap-source {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 10px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: 6px;
}

.ap-source-outlet {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-secondary);
}

.ap-source-headline {
  font-size: 13px;
  color: var(--text-primary);
  text-decoration: none;
  line-height: 1.35;
}

a.ap-source-headline:hover {
  color: var(--accent);
  text-decoration: underline;
}

.ap-source-date {
  font-size: 11px;
  color: var(--text-muted);
}

.ap-source-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.ap-feed-link {
  background: none;
  border: none;
  color: var(--accent-soft);
  font-size: 11px;
  cursor: pointer;
  padding: 2px 4px;
  flex-shrink: 0;
}

.ap-feed-link:hover {
  text-decoration: underline;
}

.ap-connections {
  list-style: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.ap-connection {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  text-align: left;
  background: none;
  border: 1px solid transparent;
  border-radius: 6px;
  padding: 6px 8px;
  color: var(--text-primary);
  font-size: 13px;
  cursor: pointer;
}

.ap-connection:hover,
.ap-connection:focus-visible {
  background: var(--bg-elevated);
  border-color: var(--border-color);
  outline: none;
}

.ap-connection-row.selected .ap-connection:hover,
.ap-connection-row.selected .ap-connection:focus-visible {
  background: color-mix(in srgb, var(--accent) 21%, var(--bg-panel));
  border-color: var(--accent);
}

.ap-conn-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}

.ap-conn-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ap-conn-meta {
  font-size: 11px;
  flex-shrink: 0;
}

.ap-connection {
  flex-wrap: wrap;
}

.ap-conn-strength {
  flex-basis: 100%;
  padding-left: 18px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-muted);
  text-align: left;
}

/* ---------- §4.4 mobile bottom sheet ---------- */

/* Scrim behind the sheet; tap-to-close (rendered only on mobile). */
.ap-scrim {
  position: fixed;
  inset: 0;
  z-index: 65;
  background: rgba(0, 0, 0, 0.55);
}

.ap-sheet-handle {
  display: none;
}

@media (max-width: 767px) {
  .article-panel.sheet-mode {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 70;
    width: 100%;
    max-width: none;
    border-left: none;
    border-top: 1px solid var(--border-color);
    border-radius: 14px 14px 0 0;
    padding-top: 4px;
    padding-bottom: calc(18px + env(safe-area-inset-bottom));
    animation: ap-slide-up 0.22s ease-out;
    box-shadow: 0 -8px 30px rgba(0, 0, 0, 0.45);
  }

  .ap-evidence-axes {
    grid-template-columns: 1fr;
  }
  .article-panel.sheet-mode.pinned {
    border-top-color: var(--accent);
  }

  .ap-sheet-handle {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 44px;
    cursor: grab;
    touch-action: none;
  }

  .ap-sheet-handle:active {
    cursor: grabbing;
  }

  .ap-sheet-grip {
    width: 44px;
    height: 5px;
    border-radius: 3px;
    background: var(--border-strong);
  }

  @keyframes ap-slide-up {
    from {
      transform: translateY(30vh);
      opacity: 0;
    }
    to {
      transform: translateY(0);
      opacity: 1;
    }
  }
}

/* ---------- Causal timeline view (§2.4) ---------- */

.timeline-view {
  flex: 1;
  overflow-y: auto;
  padding: var(--view-pad-top) 32px 48px;
  max-width: 860px;
}

.timeline-intro h2 {
  font-size: 20px;
  margin-bottom: 6px;
}

.timeline-intro p {
  color: var(--text-secondary);
  font-size: 13px;
  margin-bottom: 24px;
}

.timeline {
  list-style: none;
  padding: 0 0 0 20px;
  border-left: 2px solid var(--border-color);
}

.timeline-item {
  position: relative;
  margin-bottom: 22px;
}

.timeline-marker {
  position: absolute;
  left: -27px;
  top: 18px;
  width: 12px;
  height: 12px;
  background: var(--bg-page);
  border: 3px solid var(--accent);
  clip-path: polygon(
    30% 0%, 70% 0%, 100% 30%, 100% 70%, 70% 100%, 30% 100%, 0% 70%, 0% 30%
  );
}

.timeline-card {
  background: var(--bg-panel);
  border: var(--border-width) solid var(--border-color);
  border-radius: var(--card-radius);
  padding: var(--card-pad-y) var(--card-pad-x);
}

.timeline-date {
  font-size: 12px;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
  margin-bottom: 4px;
}

.timeline-card h3 {
  font-size: 15px;
  margin-bottom: 4px;
}

.timeline-confidence {
  display: block;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}

.timeline-card p {
  font-size: 13px;
  line-height: 1.55;
  color: var(--text-body);
  margin-bottom: 8px;
}

.timeline-links {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.timeline-link {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-secondary);
}

.timeline-link em {
  color: var(--text-muted);
  font-style: normal;
}

.timeline-link i {
  display: inline-block;
  width: 22px;
  border-top: 3px solid var(--accent);
  border-radius: 2px;
}

/* ---------- Story Arcs view (§2.5) ---------- */

.arcs-view {
  flex: 1;
  min-height: 0;
  display: flex;
}

.arcs-list {
  width: 300px;
  flex-shrink: 0;
  overflow-y: auto;
  padding: var(--view-pad-top) 20px 20px;
  border-right: 1px solid var(--border-color);
  background: var(--bg-inset);
}

.arcs-list h2 {
  font-size: 17px;
  margin-bottom: 6px;
}

.arcs-sub {
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.5;
  margin-bottom: 16px;
}

/* Sidebar arc search (2026-08-10): reuses .news-search styling. */
.arcs-list .news-search {
  margin-bottom: 12px;
}

.arc-list-item {
  display: flex;
  flex-direction: column;
  gap: 3px;
  width: 100%;
  text-align: left;
  background: none;
  border: var(--border-width) solid var(--border-color);
  border-radius: var(--card-radius);
  padding: var(--card-pad-y) var(--card-pad-x);
  margin-bottom: 8px;
  color: var(--text-primary);
  cursor: pointer;
  position: relative;
  padding-left: 28px;
}

.arc-list-item:hover {
  border-color: var(--accent);
}

.arc-list-item.selected {
  border-color: var(--accent);
  background: rgba(var(--accent-rgb), 0.08);
}

/* C6: dot centers on the FIRST line of the title, not the text block. */
.arc-status-dot {
  position: absolute;
  left: 12px;
  top: calc(var(--card-pad-y) + 5px);
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.arc-list-title {
  font-size: 13px;
  line-height: 1.35;
}

.arc-list-meta {
  font-size: 11px;
  color: var(--text-muted);
}

.arc-panel {
  flex: 1;
  min-width: 0;
  overflow-y: auto;
  padding: var(--view-pad-top) 32px 48px;
  max-width: 860px;
}

.arc-panel-title-row {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.arc-panel-title-row h2 {
  font-size: 19px;
  flex: 1;
}

.arc-status-badge {
  flex-shrink: 0;
  padding: 3px 12px;
  border: 1px solid;
  border-radius: 999px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.arc-category {
  display: block;
  font-size: 12px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin: 6px 0 12px;
}

.arc-summary {
  font-size: 13px;
  line-height: 1.6;
  color: var(--text-body);
  margin-bottom: 16px;
}

.arc-age-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.arc-age-row .ap-label {
  margin-bottom: 0;
}

.arc-age-bar {
  flex: 1;
  height: 6px;
  border-radius: 3px;
  background: var(--border-color);
  overflow: hidden;
}

.arc-age-fill {
  height: 100%;
  background: var(--accent);
  border-radius: 3px;
}

.arc-age-label {
  font-size: 12px;
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
}

.arc-coverage-gap {
  border: var(--border-width) solid var(--cat-red);
  background: rgba(255, 82, 82, 0.1);
  color: var(--red-soft);
  border-radius: var(--card-radius);
  padding: var(--card-pad-y) var(--card-pad-x);
  font-size: 13px;
  line-height: 1.5;
}

/* ---------- Tier 1.2: arc status interface (spec §2.5.4) ----------
   One coherent status panel at the top of the arc detail, composing the
   derived status, coverage-gap bar, milestone checklist, and consequence
   timeline. */

.arc-status-panel {
  display: flex;
  flex-direction: column;
  gap: 18px;
  margin-top: 20px;
  border: var(--border-width) solid var(--border-color);
  background: var(--bg-panel);
  border-radius: var(--card-radius);
  padding: var(--card-pad-y) var(--card-pad-x);
}

.arc-status-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  border-bottom: var(--border-width) solid var(--border-color);
  padding-bottom: 10px;
}

.arc-status-head .ap-label {
  margin-bottom: 0;
}

.arc-status-value {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.arc-status-panel .gap-bar {
  margin-bottom: 0;
}

.arc-status-subsection {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.arc-empty {
  font-size: 13px;
  color: var(--text-muted);
  border: 1px dashed var(--border-color);
  border-radius: var(--card-radius);
  padding: var(--card-pad-y) var(--card-pad-x);
}

.arc-event-trigger {
  color: var(--accent);
  font-weight: var(--fw-label);
}

.arc-milestones {
  list-style: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.arc-milestone {
  display: flex;
  gap: 10px;
  background: var(--bg-panel);
  border: var(--border-width) solid var(--border-color);
  border-radius: var(--card-radius);
  padding: var(--card-pad-y) var(--card-pad-x);
}

.arc-milestone-status {
  font-size: 15px;
  line-height: 1.4;
}

.arc-milestone-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.arc-milestone-title {
  font-size: 13px;
}

.arc-milestone-meta {
  font-size: 11px;
}

.arc-milestone-notes {
  font-size: 12px;
  color: var(--text-secondary);
}

.arc-events {
  list-style: none;
  padding: 0 0 0 20px;
  border-left: 2px solid var(--border-color);
}

.arc-event {
  position: relative;
  margin-bottom: 18px;
}

.arc-event-body {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.arc-event-date {
  font-size: 12px;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.arc-event-title {
  font-size: 14px;
}

.arc-event-meta {
  display: flex;
  gap: 10px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.arc-event-category {
  color: var(--text-secondary);
}

.arc-event-desc {
  font-size: 13px;
  line-height: 1.55;
  color: var(--text-body);
}

/* ---------- Pass B: mobile layout & quality floor ---------- */

/* No horizontal page scroll: the shell clamps, and every flex child that
   can grow past the viewport gets min-width: 0 (see .graph-area, .arc-panel). */
html,
body {
  overflow-x: hidden;
}

.app {
  overflow-x: hidden;
  min-width: 0;
}

.app-main {
  min-width: 0;
}

/* Visible keyboard focus rings everywhere. */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.news-search:focus,
.graph-search input:focus {
  outline: 2px solid var(--accent);
  outline-offset: 0;
}

/* Respect reduced-motion preferences. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Info button: mobile-only entry to the About sheet (full product name). */
.info-btn {
  display: none;
  background: none;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-secondary);
  min-width: 44px;
  min-height: 44px;
  font-size: 18px;
  cursor: pointer;
  margin-left: auto;
}

.info-btn:hover {
  color: var(--text-primary);
  border-color: var(--accent);
}

/* R4.75 Step 3 — Explore / Change Topic. Same header chrome as nav-tab /
   info-btn. Stays visible on mobile (sibling of .app-nav, not inside it). */
.explore-btn {
  background: none;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 13px;
  padding: 5px 12px;
  cursor: pointer;
}

.explore-btn:hover,
.explore-btn[aria-expanded='true'] {
  color: var(--text-primary);
  border-color: var(--accent);
}

.explore-btn[aria-expanded='true'] {
  background: rgba(var(--accent-rgb), 0.12);
}

/* ---------- Bottom sheets (filters, about) ---------- */

.sheet-backdrop {
  position: fixed;
  inset: 0;
  z-index: 60;
  background: rgba(0, 0, 0, 0.55);
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.sheet {
  width: 100%;
  max-width: 560px;
  max-height: 80vh;
  overflow-y: auto;
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-bottom: none;
  border-radius: 14px 14px 0 0;
  padding: 16px 20px calc(24px + env(safe-area-inset-bottom));
}

.sheet-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.sheet-head h2 {
  font-size: 17px;
}

.sheet-close {
  background: none;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-secondary);
  min-width: 44px;
  min-height: 44px;
  font-size: 20px;
  cursor: pointer;
  line-height: 1;
}

.sheet-close:hover {
  color: var(--text-primary);
  border-color: var(--accent);
}

.sheet-body {
  font-size: 15px;
  line-height: 1.55;
  color: var(--text-body);
  margin-bottom: 10px;
}

.sheet-body.muted {
  color: var(--text-muted);
}

/* ---------- More sheet (Track B nav restructure) ---------- */

.more-list {
  display: flex;
  flex-direction: column;
}

.more-item {
  display: block;
  width: 100%;
  min-height: 48px;
  padding: 12px 4px;
  background: none;
  border: none;
  border-bottom: 1px solid var(--border-color);
  color: var(--text-primary);
  font-size: 16px;
  text-align: left;
  cursor: pointer;
}

.more-item:last-child {
  border-bottom: none;
}

.more-item:hover {
  color: var(--accent);
}

.sheet .ap-label {
  margin-top: 12px;
}

.sheet .news-filter-row {
  margin-bottom: 6px;
}

.sheet-done {
  margin-top: 18px;
  width: 100%;
  min-height: 48px;
  background: rgba(var(--accent-rgb), 0.12);
  border: 1px solid var(--accent);
  border-radius: 8px;
  color: var(--text-primary);
  font-size: 15px;
  cursor: pointer;
}

/* Explore reuses .sheet; taller so the existing News discovery list is usable. */
.explore-sheet {
  max-width: 720px;
  max-height: 88vh;
}

/* ---------- Fixed bottom tab bar (mobile) ---------- */

.bottom-nav {
  display: none;
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 50;
  background: var(--bg-panel);
  border-top: 1px solid var(--border-color);
  padding-bottom: env(safe-area-inset-bottom);
}

/* flex: 1 per tab keeps the bar usable when a fifth tab is added. */
.bottom-tab {
  flex: 1 1 0;
  min-width: 0;
  min-height: 56px;
  background: none;
  border: none;
  border-top: 2px solid transparent;
  color: var(--text-secondary);
  font-size: 15px;
  cursor: pointer;
  padding: 6px 2px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bottom-tab.active {
  color: var(--text-primary);
  border-top-color: var(--accent);
  background: rgba(var(--accent-rgb), 0.12);
}

/* ---------- Mobile graph entry: ranked hub list ---------- */

.hub-list {
  flex: 1;
  overflow-y: auto;
  padding: var(--view-pad-top) 20px 48px;
}

.hub-list h2 {
  font-size: 18px;
  margin-bottom: 6px;
}

.hub-sub {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.5;
  margin-bottom: 16px;
}

.hub-items {
  list-style: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.hub-item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 48px;
  text-align: left;
  background: var(--bg-panel);
  border: var(--border-width) solid var(--border-color);
  border-radius: var(--card-radius);
  padding: var(--card-pad-y) var(--card-pad-x);
  color: var(--text-primary);
  cursor: pointer;
}

.hub-item:hover {
  border-color: var(--accent);
}

.hub-rank {
  color: var(--text-muted);
  font-size: 15px;
  font-variant-numeric: tabular-nums;
  min-width: 20px;
}

.hub-label {
  flex: 1;
  min-width: 0;
  font-size: 15px;
  line-height: 1.35;
}

.hub-meta {
  flex-shrink: 0;
  /* Defense-in-depth (2026-08-14): with flex-shrink: 0 the meta keeps its
     intrinsic width; min-width: 0 plus wrap means a pathologically long
     meta value (e.g. the e7e35b9 UUID-in-degree regression) wraps within
     its own box instead of forcing the title column to near-zero width. */
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--text-muted);
  font-size: 15px;
}

.hub-show-all {
  margin-top: 16px;
  width: 100%;
  min-height: 48px;
  background: var(--bg-panel);
  border: 1px solid var(--accent);
  border-radius: 8px;
  color: var(--accent-soft);
  font-size: 15px;
  cursor: pointer;
}

/* Mobile graph mode controls, floating above the canvas. Anchored
   bottom-LEFT; the EdgeControls panel stacks above it. */
.graph-mobile-bar {
  position: absolute;
  bottom: calc(16px + env(safe-area-inset-bottom));
  left: calc(16px + env(safe-area-inset-left));
  right: auto;
  z-index: 10;
  display: flex;
  gap: 8px;
}

.graph-mode-btn {
  min-height: 44px;
  padding: 8px 14px;
  background: rgba(var(--bg-panel-rgb), 0.95);
  border: 1px solid var(--accent);
  border-radius: 8px;
  color: var(--accent-soft);
  font-size: 15px;
  cursor: pointer;
}

/* ---------- Graph view controls (bottom-right floating layer) ---------- */

/* Track B Step 2 item 2: plain buttons, no joystick metaphor. A vertical
   stack bottom-right: zoom in/out, Fit (fit graph to viewport), Reset
   (re-run the layout). Clear of the fixed bottom tab bar on mobile. */
.graph-view-controls {
  position: absolute;
  bottom: calc(16px + env(safe-area-inset-bottom));
  right: calc(16px + env(safe-area-inset-right));
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  transition: opacity 150ms ease;
}

/* Faded + inert while a mobile bottom sheet (article/policy panel) is
   open so it never interferes with the sheet's drag-handle zone. */
.graph-view-controls.dimmed {
  opacity: 0.2;
  pointer-events: none;
}

.graph-view-btn {
  min-width: 44px;
  min-height: 36px;
  padding: 4px 12px;
  background: rgba(var(--bg-panel-rgb), 0.95);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1;
  cursor: pointer;
}

.graph-view-btn:hover {
  color: var(--text-primary);
  border-color: var(--border-strong);
}

/* ---------- Story Arcs: split-pane only >= 1024px ---------- */

.arc-back-btn {
  display: none;
  background: none;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  color: var(--accent-soft);
  min-height: 44px;
  padding: 8px 14px;
  font-size: 15px;
  cursor: pointer;
  margin-bottom: 14px;
}

.arc-back-btn:hover {
  border-color: var(--accent);
}

@media (max-width: 1023px) {
  .arcs-view {
    flex-direction: column;
  }

  .arcs-list {
    width: 100%;
    border-right: none;
  }

  .arc-panel {
    display: none;
    max-width: none;
    padding: 20px 20px 64px;
  }

  /* Tapping an arc pushes the full-screen detail; back returns to the list. */
  .arcs-view.detail-open .arcs-list {
    display: none;
  }

  .arcs-view.detail-open .arc-panel {
    display: block;
    width: 100%;
  }

  .arc-back-btn {
    display: block;
  }
}

/* ---------- Mobile (< 768px) ---------- */

@media (max-width: 767px) {
  /* Compact header: wordmark + info button only. */
  .app-header {
    align-items: center;
    padding: 8px 16px;
    gap: 10px;
  }

  .app-header h1 {
    font-size: 18px;
  }

  .app-header .subtitle,
  .app-header .app-nav,
  .app-header .data-source {
    display: none;
  }

  .ic-bar {
    padding: 6px 16px 8px;
  }

  .ic-bar-fields > div {
    min-width: 9rem;
  }

  .info-btn {
    display: block;
    margin-left: 0;
  }

  .explore-btn {
    margin-left: auto;
    min-height: 44px;
    font-size: 13px;
    padding: 8px 10px;
  }

  .bottom-nav {
    display: flex;
  }

  /* Keep view content clear of the fixed bottom bar. */
  .app-main {
    padding-bottom: calc(58px + env(safe-area-inset-bottom));
  }

  /* Tap targets >= 44px and no text below 15px on mobile. */
  .nav-tab,
  .news-chip,
  .ap-icon-btn,
  .ap-connection,
  .ap-feed-link {
    min-height: 44px;
  }

  .ap-icon-btn {
    min-width: 44px;
    font-size: 18px;
  }

  .news-chip {
    padding: 10px 16px;
    font-size: 15px;
  }

  .legend,
  .legend-collapsed,
  .legend-note,
  .legend h3 {
    font-size: 15px;
  }

  .ap-label,
  .ap-tag,
  .ap-muted,
  .ap-sources-error,
  .ap-source-outlet,
  .ap-source-headline,
  .ap-source-date,
  .ap-conn-meta,
  .ap-conn-strength,
  .ap-feed-link,
  .ap-connection,
  .ap-summary,
  .arc-list-title,
  .arc-list-meta,
  .arcs-sub,
  .arc-category,
  .arc-summary,
  .arc-status-badge,
  .arc-age-label,
  .arc-coverage-gap,
  .arc-status-value,
  .arc-empty,
  .arc-event-trigger,
  .arc-milestone-title,
  .arc-milestone-meta,
  .arc-milestone-notes,
  .arc-event-date,
  .arc-event-title,
  .arc-event-meta,
  .arc-event-desc,
  .timeline-date,
  .timeline-card h3,
  .timeline-card p,
  .timeline-confidence,
  .timeline-link,
  .timeline-intro p,
  .graph-search-results button,
  .graph-search-type {
    font-size: 15px;
  }

  /* §4.4: on mobile the panel is a fixed bottom sheet (see .sheet-mode
     rules above) — it leaves the flex flow, so the graph keeps full height. */
  .article-panel {
    width: 100%;
    max-width: none;
  }

  .graph-layout {
    flex-direction: column;
  }

  .graph-empty-state {
    margin: 16px;
    padding: 20px;
  }

  .graph-area {
    flex: 1;
    min-height: 0;
  }

  /* Track B Step 2 item 1: mobile keeps the same in-flow structure —
     toolbar wraps, rail collapses to a horizontal strip above the canvas. */
  .graph-toolbar {
    flex-wrap: wrap;
  }

  .graph-toolbar .graph-search {
    flex: 1 1 100%;
  }

  .graph-layout {
    --graph-canvas-min: 280px;
  }

  .graph-body {
    flex-direction: column;
    min-height: 0;
  }

  .graph-rail {
    flex: 0 0 auto;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: flex-start;
    max-height: 40vh;
    border-right: none;
    border-bottom: 1px solid var(--border-color);
  }

  .graph-rail .legend {
    flex: 1 1 100%;
  }

  .graph-stage {
    flex: 1;
    min-height: var(--graph-canvas-min);
  }

  /* The mobile graph may retain card elements through an asynchronous Cytoscape
     layout frame, but only the reader’s focused node may ever be visible as a
     detail box. Every other node stays a compact canvas shape. */
  .graph-cards .graph-card {
    display: none;
  }

  .graph-cards .graph-card.mobile-active {
    display: grid;
  }

  .graph-search input {
    font-size: 15px;
    min-height: 44px;
  }

  /* Focus trail is in-flow below the toolbar on all viewports. */
  .focus-trail {
    max-width: none;
    font-size: 15px;
  }

  .focus-crumb-btn,
  .focus-show-all {
    font-size: 15px;
    min-height: 44px;
  }

  .focus-back {
    min-width: 44px;
    min-height: 44px;
  }

  .graph-controls {
    font-size: 15px;
  }

  .graph-control-label {
    font-size: 12px;
  }

  .graph-stepper-btn {
    min-width: 44px;
    min-height: 44px;
  }

  .graph-topics-btn {
    min-height: 44px;
    font-size: 15px;
  }

  .edge-evidence {
    left: 8px !important;
    right: 8px;
    top: auto !important;
    bottom: 16px;
    width: auto;
    max-height: 50vh;
    font-size: 15px;
  }

  .ap-conn-evidence {
    min-width: 44px;
    min-height: 44px;
  }

  .timeline-view {
    padding: 20px 20px 48px;
  }
}

/* ---------- Pass C: numeric language (C5) ----------
   The timeline's "92% DOCUMENTED" treatment (mono, uppercase, colored by
   confidence) becomes the app-wide standard for numbers and timestamps. */
.timeline-date,
.timeline-confidence,
.arc-age-label,
.arc-event-date,
.news-date,
.ap-source-date,
.ap-confidence-value,
.hub-rank,
.hub-meta,
.news-count,
.news-cit-strength {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.timeline-confidence,
.ap-confidence-value,
.hub-meta .num,
.news-count .num {
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* ---------- Pass C: coverage-gap bar (C6, signature element) ---------- */

.gap-bar {
  border: var(--border-width) solid var(--border-color);
  background: var(--bg-panel);
  border-radius: var(--card-radius);
  padding: var(--card-pad-y) var(--card-pad-x);
  margin-bottom: 16px;
}

.gap-bar-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  margin-bottom: 8px;
  /* §2.7: let the metric row wrap instead of clipping on narrow viewports. */
  flex-wrap: wrap;
}

.gap-bar-title {
  font-size: var(--fs-label);
  font-weight: var(--fw-label);
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
}

.gap-bar-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  font-size: var(--fs-meta);
  color: var(--text-secondary);
}

/* §2.7: short metric labels only render on narrow viewports (see the
   480px media query below); full labels are the default. */
.gap-bar-stats .stat-short {
  display: none;
}

@media (max-width: 480px) {
  .gap-bar-stats .stat-full {
    display: none;
  }
  .gap-bar-stats .stat-short {
    display: inline;
  }
  .gap-bar-stats {
    gap: 4px 10px;
  }
}

.gap-bar-stats .num {
  color: var(--accent-soft);
  text-transform: uppercase;
}

.gap-bar-stats .num.gap-flag {
  color: var(--cat-red);
}

.gap-bar-track {
  display: flex;
  gap: 3px;
  height: 10px;
}

.gap-seg {
  flex: 1 1 0;
  min-width: 0;
  border-radius: 2px;
  border: 1px solid var(--border-color);
  background: var(--bg-inset);
}

.gap-seg.covered {
  background: var(--accent);
  border-color: var(--accent);
}

.gap-seg.gap {
  background: rgba(255, 82, 82, 0.16);
  border-color: var(--cat-red);
}

.gap-bar-foot {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: 6px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
}

/* Track B Step 2 (2026-08-10): label for the disconnected-node band.
   Plain text documentation — no box, so it can't read as a container. */
.graph-band-label {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 2;
  pointer-events: none;
  font-size: 12px;
  color: var(--text-secondary, #9ca3af);
  letter-spacing: 0.02em;
}

/* --- Track B Step 2b: card nodes + region boundaries (2026-08-18) --------
   Cards and region labels are DOM (200% text scaling applies natively).
   Boundary dashes render on .graph-regions UNDER the cytoscape canvas, so
   they can never obscure edges. Meaning never rides on color alone: cards
   carry icon + name + type label; regions carry a dashed stroke + an
   always-visible text label. */
.graph-regions {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
}
.graph-cards {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  overflow: hidden;
}
.graph-card {
  position: absolute;
  top: 0;
  left: 0;
  width: 160px;
  min-height: 64px;
  padding: 8px 10px;
  background: var(--bg-panel, #ffffff);
  border: 1.5px solid var(--border-strong, #8a8a80);
  border-radius: 12px;
  display: grid;
  grid-template-columns: 18px 1fr;
  grid-template-rows: auto auto auto;
  column-gap: 6px;
  align-items: start;
  pointer-events: auto;
  cursor: pointer;
  font-family: Inter, "IBM Plex Sans", system-ui, sans-serif;
  color: var(--text-primary, #1a1a17);
  box-sizing: border-box;
}
.graph-card-icon {
  grid-row: 1 / span 3;
  color: var(--text-secondary, #5c5c55);
  padding-top: 1px;
}
.graph-card-name {
  font-weight: 600;
  font-size: 12px;
  line-height: 1.25;
  overflow-wrap: anywhere;
}
.graph-card-date {
  font-size: 10px;
  color: var(--text-secondary, #5c5c55);
}
.graph-card-type {
  font-size: 10px;
  color: var(--text-secondary, #5c5c55);
  letter-spacing: 0.02em;
}
.graph-card.selected {
  background: var(--bg-selected, #dce9f7);
  border-width: 2.5px;
}
.graph-region-labels {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  overflow: hidden;
}
.graph-region-label {
  position: absolute;
  top: 0;
  left: 0;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--text-primary, #1a1a17);
  background: var(--bg-page, #f7f7f4);
  padding: 1px 6px;
  border-radius: 4px;
}
.graph-region-badge {
  position: absolute;
  top: 0;
  left: 0;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-primary, #1a1a17);
  background: var(--bg-panel, #ffffff);
  border: 1px solid var(--border-strong, #8a8a80);
  border-radius: 999px;
  padding: 1px 7px;
}

/* Package 3 item 19 — explicit reader state for a focused node with no
   documented relationships. This is intentionally a small anchored card, not
   a graph annotation or a fabricated connector. */
.graph-isolated-reader {
  position: absolute;
  left: 14px;
  bottom: 14px;
  z-index: 8;
  max-width: min(360px, calc(100% - 88px));
  padding: 11px 12px;
  border: 1px solid var(--border-color);
  border-left: 3px solid var(--accent);
  border-radius: 10px;
  background: var(--surface, #fff);
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.12);
  color: var(--text-body);
}
.graph-isolated-reader strong {
  display: block;
  margin-bottom: 4px;
  font-size: 13px;
}
.graph-isolated-reader p {
  margin: 3px 0;
  font-size: 12px;
  line-height: 1.35;
}
.graph-isolated-reader button {
  margin-top: 8px;
  border: 1px solid var(--accent);
  border-radius: 7px;
  padding: 5px 8px;
  background: transparent;
  color: var(--accent);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}
.graph-isolated-reader button:hover,
.graph-isolated-reader button:focus-visible {
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}
@media (max-width: 767px) {
  .graph-isolated-reader {
    left: 10px;
    bottom: 10px;
    max-width: calc(100% - 90px);
    padding: 9px 10px;
  }
}

/* Focused Graph workspace — Screen 6 controls. The canvas remains the
   Relationships mode; Geography and Time are data-backed record lists rather
   than inferred maps or chronologies. */
.graph-workspace-controls {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-panel);
}
.graph-workspace-tabs {
  display: inline-flex;
  gap: 3px;
  padding: 3px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: var(--bg-elevated);
}
.graph-workspace-tab {
  min-height: 30px;
  border: 0;
  border-radius: 5px;
  padding: 4px 9px;
  background: transparent;
  color: var(--text-secondary);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}
.graph-workspace-tab:hover,
.graph-workspace-tab:focus-visible {
  color: var(--text-primary);
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}
.graph-workspace-tab.active {
  background: var(--bg-panel);
  color: var(--text-primary);
  box-shadow: 0 1px 3px color-mix(in srgb, var(--text-primary) 12%, transparent);
}
.graph-investigation-filters {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.graph-investigation-filters .filter-family-label {
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.graph-region-filter {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-secondary);
  font-size: 12px;
  white-space: nowrap;
}
.graph-region-filter select {
  min-height: 30px;
  max-width: 168px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 4px 24px 4px 8px;
  background: var(--bg-elevated);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
}
.graph-scope-status {
  margin: 0 0 0 auto;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.3;
}
.graph-mode-panel {
  flex: 1;
  min-width: 0;
  overflow: auto;
  padding: 20px;
  background: var(--bg-main);
}
.graph-mode-panel-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  max-width: 780px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border-color);
}
.graph-mode-panel h2 {
  margin: 2px 0 0;
  color: var(--text-primary);
  font-size: 20px;
}
.graph-mode-eyebrow {
  margin: 0;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.graph-mode-list {
  display: grid;
  gap: 8px;
  max-width: 780px;
  margin: 16px 0 0;
  padding: 0;
  list-style: none;
}
.graph-mode-list li {
  display: grid;
  gap: 3px;
  padding: 10px 12px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: var(--bg-panel);
}
.graph-mode-primary {
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 650;
}
.graph-mode-secondary,
.graph-mode-empty {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.5;
}
.graph-mode-empty {
  max-width: 680px;
  margin: 20px 0;
  padding: 12px;
  border-left: 3px solid var(--border-strong);
  background: var(--bg-panel);
}

/* Geography is a provenance-first globe, not a decorative basemap. The panel
   names both the source-resolution status and its stated spatial precision. */
.geography-mode-content {
  max-width: 920px;
}
.geography-mode-intro {
  max-width: 780px;
  margin: 16px 0 0;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.55;
}
.geography-state-counts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  max-width: 920px;
  margin: 16px 0 0;
}
.geography-state-counts > div {
  display: grid;
  gap: 2px;
  min-height: 92px;
  padding: 11px 12px;
  border: 1px solid var(--border-color);
  border-radius: 9px;
  background: var(--bg-panel);
}
.geography-state-counts dt {
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.geography-state-counts dd {
  margin: 0;
  color: var(--text-primary);
  font-size: 25px;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  line-height: 1.05;
}
.geography-state-counts span {
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.3;
}
.geography-layout {
  display: grid;
  grid-template-columns: minmax(250px, 340px) minmax(220px, 1fr);
  align-items: center;
  gap: 18px;
  max-width: 780px;
  margin-top: 16px;
}
.geography-globe {
  width: min(100%, 330px);
  margin: 0;
  padding: 10px;
  border: 1px solid var(--border-color);
  border-radius: 14px;
  background: radial-gradient(circle at 33% 27%, color-mix(in srgb, var(--accent) 13%, var(--bg-panel)), var(--bg-panel) 65%);
  box-shadow: inset 0 1px 0 color-mix(in srgb, white 35%, transparent);
}
.geography-globe svg {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}
.geography-globe-sphere {
  fill: color-mix(in srgb, var(--accent) 12%, var(--bg-inset));
  stroke: color-mix(in srgb, var(--accent) 52%, var(--border-strong));
  stroke-width: 1.4;
}
.geography-globe-graticule {
  fill: none;
  stroke: color-mix(in srgb, var(--accent) 24%, var(--border-color));
  stroke-width: .65;
}
.geography-globe-marker {
  cursor: pointer;
  outline: none;
}
.geography-globe-marker-halo {
  fill: color-mix(in srgb, var(--accent) 24%, transparent);
  transition: transform 160ms var(--ease-out, ease-out), fill 160ms var(--ease-out, ease-out);
  transform-box: fill-box;
  transform-origin: center;
}
.geography-globe-marker-dot {
  fill: var(--accent);
  stroke: var(--bg-panel);
  stroke-width: 1.6;
}
.geography-globe-marker:hover .geography-globe-marker-halo,
.geography-globe-marker:focus .geography-globe-marker-halo {
  fill: color-mix(in srgb, var(--accent) 38%, transparent);
  transform: scale(1.45);
}
.geography-globe-marker:focus .geography-globe-marker-dot {
  stroke: var(--text-primary);
  stroke-width: 2;
}
.geography-globe figcaption {
  padding: 2px 5px 0;
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.35;
}
.geography-legend {
  padding: 14px;
  border-left: 3px solid var(--accent);
  background: color-mix(in srgb, var(--accent) 5%, var(--bg-panel));
}
.geography-legend p:not(.graph-mode-eyebrow) {
  margin: 7px 0 0;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.5;
}
.geography-legend-note {
  color: var(--text-muted) !important;
}
.geography-record-list {
  display: grid;
  gap: 8px;
  max-width: 920px;
  margin: 16px 0 0;
  padding: 0;
  list-style: none;
}
.geography-record {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  width: 100%;
  padding: 12px;
  border: 1px solid var(--border-color);
  border-radius: 9px;
  background: var(--bg-panel);
  color: inherit;
  text-align: left;
  transition: border-color 160ms var(--ease-out, ease-out), background 160ms var(--ease-out, ease-out), transform 160ms var(--ease-out, ease-out);
}
.geography-record:hover,
.geography-record:focus-visible {
  border-color: color-mix(in srgb, var(--accent) 62%, var(--border-color));
  background: color-mix(in srgb, var(--accent) 5%, var(--bg-panel));
  outline: none;
}
.geography-record:active {
  transform: scale(.99);
}
.geography-record-marker {
  width: 9px;
  height: 9px;
  margin-top: 5px;
  border: 2px solid var(--bg-panel);
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 75%, var(--border-strong));
}
.geography-record-content {
  display: grid;
  gap: 3px;
  min-width: 0;
}
.geography-record-node {
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.35;
}
.geography-record-uncertainty {
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.4;
}
.geography-record-state {
  align-self: start;
  padding: 3px 6px;
  border: 1px solid color-mix(in srgb, var(--accent) 42%, var(--border-color));
  border-radius: 999px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}
@media (max-width: 767px) {
  .graph-investigation-filters .filter-family-label {
    width: 100%;
  }
  .graph-workspace-controls {
    align-items: flex-start;
    padding: 8px 10px;
  }
  .graph-workspace-tabs {
    width: 100%;
  }
  .graph-workspace-tab {
    flex: 1;
  }
  .graph-scope-status {
    width: 100%;
    margin-left: 0;
  }
  .graph-mode-panel {
    padding: 14px 10px;
  }
  .graph-mode-panel-head {
    align-items: stretch;
    flex-direction: column;
  }
  .geography-state-counts {
    grid-template-columns: 1fr;
  }
  .geography-state-counts > div {
    min-height: 0;
  }
  .geography-layout {
    grid-template-columns: 1fr;
  }
  .geography-globe {
    justify-self: center;
  }
  .geography-legend {
    border-top: 3px solid var(--accent);
    border-left: 0;
  }
  .geography-record {
    grid-template-columns: auto minmax(0, 1fr);
  }
  .geography-record-state {
    grid-column: 2;
    justify-self: start;
  }
}

/* Reference alignment — Knowledge Graph (IMG_2995): foreground node cards use
   a visible type icon token and the small-screen rail yields more space to the
   canvas. These are presentation refinements; relationship semantics remain
   entirely in the source-backed graph data. */
.graph-card {
  border-color: color-mix(in srgb, var(--border-strong, #8a8a80) 82%, var(--accent) 18%);
  box-shadow: 0 7px 18px rgb(22 52 92 / 12%);
}
.graph-card-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 19px;
  height: 19px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background: var(--bg-inset);
  color: var(--accent);
}
.graph-card-icon svg {
  width: 13px;
  height: 13px;
}
.graph-card-name {
  font-size: 12.5px;
  letter-spacing: -0.01em;
}
.graph-card-type {
  margin-top: 1px;
  color: var(--text-muted);
  font-weight: 650;
  text-transform: uppercase;
  font-size: 9px;
  letter-spacing: 0.06em;
}
.graph-card.selected {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent), 0 9px 22px rgb(22 52 92 / 14%);
}
.graph-region-label {
  border: 1px solid var(--border-color);
  box-shadow: 0 2px 6px rgb(22 52 92 / 8%);
  font-size: 11px;
  font-weight: 720;
  text-transform: uppercase;
  letter-spacing: 0.07em;
}
@media (max-width: 767px) {
  .graph-toolbar {
    gap: 6px;
    padding: 8px 10px;
  }
  .graph-toolbar-btn {
    min-height: 38px;
    padding-inline: 10px;
  }
  .graph-rail {
    max-height: 31vh;
    gap: 8px;
    padding: 8px 10px;
    overflow-x: auto;
    overflow-y: auto;
  }
  .graph-rail .legend,
  .graph-rail .graph-controls,
  .graph-rail .topic-browser {
    min-width: min(100%, 260px);
  }
  .graph-stage {
    min-height: var(--graph-canvas-min);
  }
  .graph-cards .graph-card.mobile-active {
    width: min(260px, calc(100% - 28px));
    min-height: 72px;
    padding: 10px 12px;
    border-width: 2px;
    box-shadow: 0 10px 24px rgb(22 52 92 / 18%);
  }
  .graph-cards .graph-card.mobile-active .graph-card-name {
    font-size: 13px;
  }
  .graph-band-label {
    top: 6px;
    left: 8px;
    max-width: calc(100% - 16px);
    padding: 3px 6px;
    border-radius: 5px;
    background: color-mix(in srgb, var(--bg-panel) 88%, transparent);
    font-size: 11px;
  }
}

/* Public-data globe revision: Natural Earth land/country topology makes the
   spherical projection visibly geographic. The overlay is bounded and hides
   while a reader is open, so it provides context without covering evidence. */
.geography-globe-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 1px 4px 7px;
}
.geography-globe-kicker {
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 750;
  letter-spacing: .075em;
  text-transform: uppercase;
}
.geography-globe-reset {
  min-height: 28px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 3px 7px;
  background: var(--bg-panel);
  color: var(--text-secondary);
  font: inherit;
  font-size: 11px;
  cursor: pointer;
}
.geography-globe-reset:hover,
.geography-globe-reset:focus-visible {
  border-color: var(--accent);
  color: var(--text-primary);
  outline: none;
}
.geography-globe svg {
  cursor: grab;
  touch-action: none;
  outline: none;
}
.geography-globe svg:active { cursor: grabbing; }
.geography-globe svg:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 50%;
}
.geography-globe-land {
  fill: color-mix(in srgb, var(--accent) 18%, var(--bg-panel));
  stroke: none;
}
.geography-globe-borders {
  fill: none;
  stroke: color-mix(in srgb, var(--text-secondary) 32%, var(--border-color));
  stroke-width: .52;
  vector-effect: non-scaling-stroke;
  pointer-events: none;
}
.geography-globe-marker-label {
  fill: var(--text-primary);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .015em;
  paint-order: stroke;
  stroke: var(--bg-panel);
  stroke-width: 3px;
  stroke-linejoin: round;
  pointer-events: none;
}
.geography-globe-marker.active .geography-globe-marker-halo {
  fill: color-mix(in srgb, var(--accent) 55%, transparent);
  transform: scale(1.45);
}
.geography-globe-marker.active .geography-globe-marker-dot {
  stroke: var(--text-primary);
  stroke-width: 2.2;
}
.graph-geography-overlay {
  position: absolute;
  right: 12px;
  bottom: 12px;
  z-index: 5;
  width: 214px;
  max-width: min(214px, calc(100% - 24px));
  filter: drop-shadow(0 8px 18px rgb(18 38 68 / 18%));
}
.graph-geography-overlay .geography-globe {
  width: 100%;
  padding: 7px;
  border-color: color-mix(in srgb, var(--accent) 38%, var(--border-color));
  background: color-mix(in srgb, var(--bg-panel) 92%, var(--accent) 8%);
  backdrop-filter: blur(5px);
}
.graph-geography-overlay .geography-globe-kicker { font-size: 9px; }
.graph-geography-overlay .geography-globe-reset {
  min-height: 24px;
  font-size: 10px;
}
.graph-geography-overlay .geography-globe figcaption {
  padding: 4px 3px 0;
  font-size: 10px;
}
.graph-geography-overlay .geography-globe-sphere { stroke-width: 1.8; }
.graph-geography-overlay .geography-globe-marker-dot { stroke-width: 2; }

@media (max-width: 767px) {
  .graph-geography-overlay {
    right: 8px;
    bottom: 8px;
    width: 156px;
    max-width: calc(100% - 16px);
  }
  .graph-geography-overlay .geography-globe { padding: 5px; }
  .graph-geography-overlay .geography-globe-head { padding-bottom: 3px; }
  .graph-geography-overlay .geography-globe-kicker { font-size: 8px; }
  .graph-geography-overlay .geography-globe-reset { min-height: 22px; padding: 2px 5px; font-size: 9px; }
  .graph-geography-overlay .geography-globe figcaption { font-size: 9px; line-height: 1.25; }
  .geography-globe-marker-label { font-size: 8px; }
}

/* Graph coverage disclosure: compact by default, expandable on demand.
   Reader-facing accounting of stored graph states — not a completeness score. */
.graph-coverage-notice {
  flex: 0 0 auto;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-inset);
}
.graph-coverage-details {
  min-width: 0;
}
.graph-coverage-summary {
  list-style: none;
  cursor: pointer;
}
.graph-coverage-summary::-webkit-details-marker {
  display: none;
}
.graph-coverage-summary::before {
  content: '▸';
  float: right;
  margin-left: 8px;
  color: var(--text-muted);
  font-size: 12px;
}
.graph-coverage-details[open] .graph-coverage-summary::before {
  content: '▾';
}
.graph-coverage-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding-right: 16px;
}
.graph-coverage-compact {
  margin: 6px 0 0;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.4;
}
.graph-coverage-panel {
  padding-top: 8px;
}
.graph-coverage-kicker {
  margin: 0 0 3px;
  color: var(--text-muted);
  font-size: var(--fs-label);
  font-weight: var(--fw-label);
  letter-spacing: 0.07em;
  text-transform: uppercase;
}
.graph-coverage-heading h2 {
  margin: 0;
  color: var(--text-primary);
  font-size: 14px;
}
.graph-coverage-focus {
  flex: 0 0 auto;
  padding: 3px 7px;
  border: 1px solid var(--border-color);
  border-radius: 999px;
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11px;
}
.graph-coverage-copy {
  max-width: 900px;
  margin: 7px 0 10px;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.45;
}
.graph-coverage-metrics {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  margin: 0;
}
.graph-coverage-metrics > div {
  min-width: 0;
  padding: 8px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: var(--bg-panel);
}
.graph-coverage-metrics dt {
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.25;
}
.graph-coverage-metrics dd {
  margin: 4px 0 3px;
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 16px;
  font-weight: 600;
}
.graph-coverage-metrics span {
  display: block;
  color: var(--text-muted);
