}

function readInitialDeepLink() {
  if (typeof window === 'undefined') {
    return {
      view: 'news',
      investigationContext: emptyInvestigationContext('news'),
      linkSelection: emptyDeepLinkSelection(),
      selectionFallbacks: [],
    }
