      if (data.type === 'policy') {
        setSelected(null)
        setPinned(false)
        setPolicyNode(data)
        setInvestigationContext((ic) => {
          const subject = subjectFromGraphNode(data)
          rememberPriorSubject(ic, subject.canonical_subject_id)
          return applySubject(ic, subject)
        })
      } else {
        setPolicyNode(null)
        setSelected(data)
        setInvestigationContext((ic) => {
          const subject = subjectFromGraphNode(data)
