  const clearInvalidNewSubjectSubSelections = useCallback(() => {
    setFocusArc(null)
    setFocusArticle(null)
    setFocusTimelineEvent(null)
    setFocusTimelineArc(null)
    setFocusComparisonEvent(null)
    setActiveLocationKey(null)
  }, [])

