    (nodeKey) => {
      if (!graph) return
      resetJumpContext()
      clearInvalidNewSubjectSubSelections()
      const next = graph.nodes.find((n) => (n.id ?? n.slug) === nodeKey)
      setGraphScreen('all')
      setView('graph')
      if (next) {
        setGraphInspectorDismissed(false)
        graphInspectorDismissedSubjectRef.current = null
        setSelected(next)
