  }, [investigationContext.canonical_subject_id, investigationContext.canonical_subject_type])

  const joinDisclosures = useMemo(
    () => [
      ...shellJoinDisclosures({
        investigationContext,
        view,
        selectionFallbacks,
        graphError: error,
        edgesUnavailable: graph?.edgesUnavailable ?? null,
